// ============ REPLACE THESE DOCS WITH YOUR OWN ============
// Each doc: { title, content }. Use "## " headings inside content -
// they become the sections the assistant cites, e.g. [Returns Policy - Refunds].
const DOCS = [
  { title: 'Returns Policy', content: `## Return window
Items can be returned within 30 days of delivery in unused condition with original tags.

## Refunds
Refunds go to the original payment method within 5-7 business days of us receiving the return.

## Exchanges
Exchanges ship free. Start one from your account page under Orders.` },
  { title: 'Shipping FAQ', content: `## Delivery times
Standard shipping takes 3-5 business days. Express takes 1-2 business days.

## Order tracking
A tracking link is emailed when your order ships. Allow 24 hours for tracking to activate.

## International
We currently ship to the US and Canada only.` },
  { title: 'Product Care', content: `## Washing
Machine wash cold, hang dry. Do not bleach or iron printed areas.

## Waterproofing
Re-apply DWR spray after roughly 20 washes to restore water resistance.` },
];
// ==========================================================

const chunks = [];
for (const doc of DOCS) {
  const parts = doc.content.split(/^## /m).filter(p => p.trim());
  for (const part of parts) {
    const lines = part.split('\n');
    const section = lines[0].trim();
    const text = lines.slice(1).join('\n').trim();
    if (text) chunks.push({ docTitle: doc.title, section, text });
  }
}
const _in = $input.first().json;
const question = (_in.body && _in.body.question) ? String(_in.body.question) : String(_in.question || '');
return [{ json: { question: question.slice(0, 2000), chunks } }];

const _in = $input.first().json;
// Keyword-overlap retrieval: no vector DB, no extra API calls.
// Good for doc sets up to a few hundred sections; beyond that, swap this node for a vector store.
const STOP = new Set(['the','a','an','is','are','was','were','be','to','of','and','or','in','on','at','for','with','do','does','how','what','when','where','why','can','i','my','your','it','this','that']);
const norm = s => s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w && !STOP.has(w));
const q = norm(_in.question);
const scored = _in.chunks.map(c => {
  const inSection = new Set(norm(c.section));
  const inText = new Set(norm(c.text));
  let score = 0;
  for (const w of q) {
    if (inText.has(w)) score += 1;
    if (inSection.has(w)) score += 2; // heading matches count double
  }
  return { ...c, score };
}).sort((a, b) => b.score - a.score);
const top = scored.slice(0, 4).filter(c => c.score > 0);
return [{ json: { question: _in.question, top } }];

const _in = $input.first().json;
// Extract Claude's answer defensively; fall back loudly instead of failing silently.
let answer = '';
try {
  const content = _in.content;
  if (Array.isArray(content) && content[0] && content[0].text) answer = content[0].text.trim();
} catch (e) { /* fall through */ }
if (!answer) {
  answer = "I couldn't generate an answer right now. Please try again in a moment or contact us directly.";
}
const sources = ($('Retrieve Top Chunks').first().json.top || []).map(c => c.docTitle + ' - ' + c.section);
return [{ json: { answer, sources } }];
